import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"MAVLink Customisation","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-dev-guide/custom_build/mavlink.md","filePath":"en/qgc-dev-guide/custom_build/mavlink.md"}`),a={name:`en/qgc-dev-guide/custom_build/mavlink.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="mavlink-customisation" tabindex="-1">MAVLink Customisation <a class="header-anchor" href="#mavlink-customisation" aria-label="Permalink to “MAVLink Customisation”">​</a></h1><p>QGC communicates with flight stacks using <a href="https://mavlink.io/en/" target="_blank" rel="noreferrer">MAVLink</a>, a very lightweight messaging protocol that has been designed for the drone ecosystem.</p><p>QGC includes the <a href="https://mavlink.io/en/messages/all.html" target="_blank" rel="noreferrer">all.xml</a> dialect by default. The <code>all.xml</code> includes all other dialects in the <a href="https://github.com/mavlink/mavlink/tree/master/message_definitions/v1.0" target="_blank" rel="noreferrer">mavlink/mavlink</a> repository, and allows it to communicate with both PX4 and Ardupilot. Previous versions of QGC (v4.2.8 and earlier), used the <code>ArduPilotMega.xml</code> dialect.</p><p>In order to add support for a new set of messages you should add them to <a href="https://mavlink.io/en/messages/development.html" target="_blank" rel="noreferrer">development.xml</a>, <a href="https://mavlink.io/en/messages/ardupilotmega.html" target="_blank" rel="noreferrer">ArduPilotMega.xml</a>, or <a href="https://mavlink.io/en/messages/common.html" target="_blank" rel="noreferrer">common.xml</a> (for PX4), or fork <em>QGroundControl</em> and include your own dialect.</p><p>To modify the version of MAVLink used by QGC:</p><ul><li><p>Update the CMake MAVLink Options in <a href="https://github.com/mavlink/qgroundcontrol/tree/master/cmake/CustomOptions.cmake" target="_blank" rel="noreferrer">/qgroundcontrol/cmake/CustomOptions.cmake</a> or when using the built-in custom build support you can override these options in <a href="https://github.com/mavlink/qgroundcontrol/tree/master/custom-example/cmake/CustomOverrides.cmake" target="_blank" rel="noreferrer">/qgroundcontrol/custom/cmake/CustomOverrides.cmake</a>.</p><ul><li><p>QGC_MAVLINK_GIT_REPO - This is a link to the git repo to use, by default this is a link to <a href="https://github.com/mavlink/mavlink" target="_blank" rel="noreferrer">https://github.com/mavlink/mavlink</a>. You can also <a href="https://mavlink.io/en/getting_started/generate_libraries.html" target="_blank" rel="noreferrer">build your own libraries</a> using the MAVLink toolchain and upload to your own git repo.</p></li><li><p>QGC_MAVLINK_GIT_TAG - This points to the git tag you would like to use in the chosen repo. This should likely be updated on occasion to use the latest version of MAVLink.</p></li><li><p>You can also set the mavlink directory to a local path by using the CMake variable CPM_mavlink_SOURCE. Just add to <a href="https://github.com/mavlink/qgroundcontrol/blob/master/cmake/CustomOptions.cmake" target="_blank" rel="noreferrer">/qgroundcontrol/cmake/CustomOptions.cmake</a>:</p></li></ul><div class="language-cmake"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(CPM_mavlink_SOURCE </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/your/custom/mavlink&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div></li></ul><h2 id="_32-bit-system-ids" tabindex="-1">32-bit system IDs <a class="header-anchor" href="#_32-bit-system-ids" aria-label="Permalink to “32-bit system IDs”">​</a></h2><p>QGC supports the MAVLink 2 extensions for 32-bit system IDs and explicit header system targets provided by the upstream pymavlink generator. Vehicle and GCS system IDs use the unsigned range 1–4294967295. Set the GCS ID in MAVLink settings or with <code>--system-id</code>. Ordinary 8-bit IDs continue to use standard MAVLink headers; peers need extension support to communicate with larger IDs.</p><p>Custom MAVLink sources must include pymavlink&#39;s 32-bit system ID support and provide compatible generated headers. See the <a href="https://github.com/mavlink/qgroundcontrol/blob/master/cmake/CustomOptions.cmake" target="_blank" rel="noreferrer">CMake MAVLink options</a> for the current default repository and revision.</p><p>Message payload structs keep their existing wire layout. Use generated <code>pack</code> functions with full-width target IDs, and <code>mavlink_msg_get_target_sysid</code> when receiving messages. A decoded payload&#39;s 8-bit target field cannot represent a wide header target. Other system references embedded in payloads, such as gimbal control ownership fields, retain their protocol-defined width. For this reason QGC refuses gimbal control, and tells the user why, when its GCS system ID is above 255.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};